const CARD_INVOCATION = { actor: typeof actor === "undefined" ? null : actor, spell: typeof spell === "undefined" ? null : spell, options: typeof options === "undefined" ? null : options, cast: typeof cast === "function" ? cast : null };
await studioRunCardRecipe(CARD_RECIPE, CARD_INVOCATION, null);
